typedef enum {
    Z_OPENRESULT_TAG_OK,
    Z_OPENRESULT_TAG_ERR,
} z_t1254_tag_t;
struct z_t1254_t {
    z_t1254_tag_t tag;
    void* data;
};
static void z_t1254_destroy(z_t1254_t* u) {
    if (!u) return;
    if (!u->data) return;
    switch (u->tag) {
        case Z_OPENRESULT_TAG_OK:
            z_t74_free((z_t74_t*)u->data);
            free(u->data);
            break;
        case Z_OPENRESULT_TAG_ERR:
            z_t1255_destroy((z_t1255_t*)u->data);
            free(u->data);
            break;
        default: break;
    }
}

